/**
 * Bootstrap compatibility, not a public entry point.
 *
 * `packages/cli` is generated by the *published* CLI pinned in its `build.sh`
 * (`PIKKU_CLI_VERSION`), and that CLI's serializers still emit
 * `@pikku/core/ecosystem`. The generated file is imported for real during
 * schema generation, so the specifier has to resolve against this workspace's
 * core or the CLI cannot build itself.
 *
 * These are the only two names the pinned CLI emits from it, and
 * `bootstrap-compat.test.ts` fails if that stops being true. Delete this file,
 * its sibling, and both `exports` entries once the pin moves to a CLI released
 * from this branch.
 */
export { pikkuState } from '../pikku-state.js'
export type { CreateWireServices } from '../types/core.types.js'
